operation.add:
// SaaS Dedicated Product Tabs Injection
$data['saas_custom_tabs'] = [];
$saas_tabs_query = $this->db->query("SELECT tab_key, title, content FROM `" . DB_PREFIX . "saas_product_tabs` WHERE product_id = '" . (int)$product_id . "' AND status = 1 ORDER BY sort_order ASC");
if ($saas_tabs_query && $saas_tabs_query->num_rows > 0) {
    foreach ($saas_tabs_query->rows as $st) {
        $data['saas_custom_tabs'][] = [
            'key' => $st['tab_key'],
            'title' => $st['title'],
            'content' => html_entity_decode($st['content'], ENT_QUOTES, 'UTF-8')
        ];
    }
}

{% if saas_custom_tabs %}
    {% for ctab in saas_custom_tabs %}
        <li><a href="#tab-saas-{{ ctab.key }}" data-toggle="tab">{{ ctab.title }}</a></li>
    {% endfor %}
{% endif %}

{% if saas_custom_tabs %}
    {% for ctab in saas_custom_tabs %}
        <div class="tab-pane" id="tab-saas-{{ ctab.key }}">{{ ctab.content }}</div>
    {% endfor %}
{% endif %}

{% if saas_custom_tabs %}
    {% for ctab in saas_custom_tabs %}
        <li><a href="#tab-saas-{{ ctab.key }}" data-toggle="tab">{{ ctab.title }}</a></li>
    {% endfor %}
{% endif %}

{% if saas_custom_tabs %}
    {% for ctab in saas_custom_tabs %}
        <div class="tab-pane" id="tab-saas-{{ ctab.key }}">{{ ctab.content }}</div>
    {% endfor %}
{% endif %}
